// Экраны 2 и 3 шага 0: страница истории (простой слой и «Для изучающих»).
// Рисует всё из данные.js (данные шага 0 и стихи synodal.tsv). ПРОТОТИП: в продукт не переносится.
(function () {
  const И = window.ИСТОРИЯ, З = window.ЗНАКИ, ЗИ = window.ЗНАКИ_ИСТОРИИ, корень = document.documentElement;
  const q = new URLSearchParams(location.search);
  const ЭКРАН = корень.dataset.экран;
  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => Array.from(el.querySelectorAll(s));
  const экр = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const слой2 = () => корень.dataset.layer === '2';
  const НЕТ = 'не-нарисовано.html';
  let счётчик = 0; const новыйId = (п) => `${п}-${++счётчик}`;

  // ---------- адреса ----------
  const КНИГИ = { Быт: ['Бытие', 'книге Бытие'], Ис: ['Исаия', 'книге пророка Исаии'], Мф: ['Евангелие от Матфея'], Мк: ['Евангелие от Марка'],
    Лк: ['Евангелие от Луки'], '1Пет': ['Первое послание Петра'], '2Пет': ['Второе послание Петра'], Евр: ['Послание к Евреям'],
    Пс: ['Псалтирь'], '1Пар': ['Первая книга Паралипоменон'], Иез: ['Иезекииль'] };
  const сокр = (b) => b.replace(/^(\d)/, '$1 ');
  // «Быт 6:9-22» → «Быт 6:9–22»; «Быт 6:9-9:17» → «Быт 6:9 – 9:17»; неразрывный пробел после сокращения
  function адрес(a) {
    const m = String(a).match(/^(\S+) (.+)$/); if (!m) return a;
    let хвост = m[2].replace(/-(\d+:\d+)/, ' – $1').replace(/-(\d+)/g, '–$1');
    return `${сокр(m[1])} ${хвост}`.replace(/^(\S+(?: \S+)?) (\d)/, (x) => x.replace(/ (\d)$/, ' $1'));
  }
  function полныйАдрес(a) {
    const m = String(a).match(/^(\S+) (\d+):(\d+)(?:-(\d+))?$/); if (!m) return адрес(a);
    const кн = (КНИГИ[m[1]] || [m[1]])[0];
    return `${адрес(a)}, ${кн}, глава ${m[2]}, ${m[4] ? `стихи ${m[3]}–${m[4]}` : `стих ${m[3]}`}`;
  }
  function стихиАдреса(a) { // «Мф 24:37-39» → ['Мф 24:37', …]
    const m = String(a).match(/^(\S+) (\d+):(\d+)(?:-(\d+))?$/); if (!m) return [];
    const out = []; for (let v = +m[3]; v <= +(m[4] || m[3]); v++) out.push(`${m[1]} ${m[2]}:${v}`); return out;
  }

  // ---------- текст Писания: скобки, ссылки имён, начало части ----------
  const ОТМЕЧАЕМЫЕ = new Set(['lxx', 'added', 'slav', 'unknown']); // виды «а», «в», «г-нз», не вошедшие; «б» и «г» — как текст
  const ИМЕНА = {
    ной: [['p-noy', /(?<!\p{L})Но(?:й|я|ю|ем|е|ев\p{L}*)(?!\p{L})/u], ['p-sim', /(?<!\p{L})Сим(?:а|у|ом)?(?!\p{L})/u],
      ['p-kham', /(?<!\p{L})Хам(?:а|у|ом)?(?!\p{L})/u], ['p-iafet', /(?<!\p{L})Иафет(?:а|у|ом)?(?!\p{L})/u]],
    расслабленный: [['p-iisus', /(?<!\p{L})Иисус(?:а|у|ом)?(?!\p{L})/u]],
  }[ЭКРАН];
  function куски(ад, т) { // [{скобка:bool, отметить:bool, текст}]
    const out = []; const re = /\[[^\]]+\]|\([^)]+\)/g; let i = 0, m;
    while ((m = re.exec(т))) {
      if (m.index > i) out.push({ текст: т.slice(i, m.index) });
      const внутри = m[0].slice(1, -1);
      const запись = (И.скобки[ад] || []).find((b) => b.текст === внутри);
      out.push({ скобка: true, отметить: ОТМЕЧАЕМЫЕ.has(запись ? запись.вид : 'unknown'), текст: m[0] });
      i = m.index + m[0].length;
    }
    if (i < т.length) out.push({ текст: т.slice(i) });
    return out;
  }
  function htmlКуска(к, связано) {
    if (к.скобка) return к.отметить ? `<span class="скобка">${экр(к.текст)}</span>` : экр(к.текст);
    let h = экр(к.текст);
    for (const [id, re] of ИМЕНА) {
      if (связано.has(id)) continue;
      const m = h.match(re); if (!m) continue;
      связано.add(id);
      h = h.slice(0, m.index) + `<a href="${НЕТ}" data-лицо="${id}">${m[0]}</a>` + h.slice(m.index + m[0].length);
    }
    return h;
  }
  // часть текста: стихи подряд одним абзацем; начало части — до первой запятой, не больше 5 слов (08 § 2.5 п. 2)
  function текстЧасти(адреса, { буквица = false } = {}) {
    const связано = new Set(); let h = '';
    адреса.forEach((ад, n) => {
      const т = И.стихи[ад]; const стих = ад.split(':')[1];
      const номер = слой2() ? `<sup class="номер-стиха">${стих}</sup>` : '';
      if (n > 0) { h += ' ' + номер + куски(ад, т).map((к) => htmlКуска(к, связано)).join(''); return; }
      const слова = [...т.matchAll(/\S+/g)];
      let срез = слова.length > 5 ? слова[4].index + слова[4][0].length : т.length;
      const зап = т.indexOf(','); if (зап > 0 && зап < срез) срез = зап;
      const кк = куски(ад, т); let поз = 0; let нач = '', ост = '';
      for (const к of кк) {
        const конец = поз + к.текст.length;
        if (конец <= срез || (к.скобка && поз < срез)) нач += htmlКуска(к, связано);
        else if (поз >= срез) ост += htmlКуска(к, связано);
        else { нач += htmlКуска({ текст: к.текст.slice(0, срез - поз) }, связано); ост += htmlКуска({ текст: к.текст.slice(срез - поз) }, связано); }
        поз = конец;
      }
      if (буквица) {
        const б = нач.match(/^(<a [^>]+>)?(.)/u)[2];
        нач = нач.replace(б, '');
        h += `<span class="буквица" aria-hidden="true">${б}</span><span class="скрыто">${б}</span>`;
      }
      h += номер + `<span class="начало-части">${нач}</span>${ост}`;
    });
    return h;
  }

  // ---------- общие части ----------
  function вклейка(ад, { подпись = '' } = {}) {
    const свои = стихиАдреса(ад); if (!свои.length || !(свои[0] in И.стихи)) return `<span class="к-адрес">${адрес(ад)}</span>`;
    const [кн, гл] = [свои[0].split(' ')[0], свои[0].split(' ')[1].split(':')[0]];
    const от = +свои[0].split(':')[1], до = +свои[свои.length - 1].split(':')[1];
    const вокруг = свои.length === 1 ? 2 : 0; const стихи = [];
    for (let v = от - вокруг; v <= до + вокруг; v++) { const к = `${кн} ${гл}:${v}`; if (к in И.стихи) стихи.push(к); }
    const id = новыйId('вклейка');
    return `<span class="вклейка-место"><button type="button" class="адрес-кнопка" aria-expanded="false" aria-controls="${id}" aria-label="${экр(полныйАдрес(ад))}">${подпись}${адрес(ад)}${З.значок('раскрыть')}</button>` +
      `<span class="вклейка" id="${id}" hidden><span class="вклейка__стихи голос-библии">${стихи.map((к) => `<span class="вклейка__стих${свои.includes(к) ? ' свой' : ''}"><span class="к-номер-стиха">${к.split(':')[1]}</span> ${куски(к, И.стихи[к]).map((x) => x.скобка && x.отметить ? `<span class="скобка">${экр(x.текст)}</span>` : экр(x.текст)).join('')}</span>`).join(' ')}</span>` +
      `<a class="вклейка__глава" href="${НЕТ}">Вся глава</a></span></span>`;
  }
  const цитата = (ц, ст) => `<span class="цитата-строка"><span class="цитата-строка__слова">Библия: «${экр(ц)}»</span> ${вклейка(ст)}</span>`;
  const состояние = (знак, слова, голос = 'библия') => `<p class="состояние состояние--${голос}"><span class="состояние__знак">${З.значок(знак)}</span><span class="состояние__текст">${слова}</span></p>`;
  const блок = (id, заголовок, тело, класс = '') => `<section class="блок ${класс}" id="${id}" aria-labelledby="${id}-з"><h2 class="к-заголовок-блока блок__заголовок" id="${id}-з">${заголовок}</h2>${тело}</section>`;
  const путь = (п) => `<nav class="путь" aria-label="Путь"><ol>${п.map((x, i) => `<li>${i ? '<span class="путь__знак" aria-hidden="true">›</span>' : ''}<a href="${НЕТ}">${экр(x)}</a></li>`).join('')}</ol></nav>`;

  // полоса 66 книг § 7.12
  const РАЗДЕЛЫ = [5, 12, 5, 17, 4, 1, 7, 14, 1];
  function полоса(как) {
    let i = 0; const завет = [[], []];
    РАЗДЕЛЫ.forEach((n, р) => {
      const клетки = И.книги.slice(i, i + n).map((кн) => {
        const в = как[кн]; return `<span class="полоса-66__клетка${в === 'рассказ' ? ' полоса-66__клетка--рассказано' : в ? ' полоса-66__клетка--упомянуто' : ''}"></span>`;
      }).join('');
      завет[р < 4 ? 0 : 1].push(`<span class="полоса-66__раздел" style="flex:${n} 1 0">${клетки}</span>`);
      i += n;
    });
    return `<div class="полоса-66" aria-hidden="true"><div class="полоса-66__ряды"><span class="полоса-66__завет">${завет[0].join('')}</span><span class="полоса-66__завет полоса-66__завет--нз">${завет[1].join('')}</span></div>` +
      `<div class="полоса-66__подписи к-адрес"><span>Ветхий Завет</span><span>Новый Завет</span></div></div>`;
  }
  // указатель эпох: 16 равных клеток, залита эпоха истории (08 § 7.5.1)
  function эпохи(id) {
    const н = И.эпохи.findIndex((e) => e.id === id); const э = И.эпохи[н];
    return `<span class="эпохи" aria-hidden="true">${И.эпохи.map((e, i) => `<span class="эпохи__клетка${i === н ? ' эпохи__клетка--эта' : ''}${i === 15 ? ' эпохи__клетка--после' : ''}"></span>`).join('')}</span>` +
      `<span class="образ__ответ">${экр(э.имя)}</span>`;
  }
  function образ(вопрос, инструмент, тело, { широкий = false } = {}) {
    return `<li class="образ${широкий ? ' образ--широкий' : ''}"><a class="образ__ссылка" href="${НЕТ}"><span class="образ__вопрос">${вопрос}</span><span class="образ__инструмент">${инструмент}</span><span class="образ__поле">${тело}</span></a></li>`;
  }
  const образНет = (вопрос, строка, знак, широкий = false) => `<li class="образ образ--нет${широкий ? ' образ--широкий' : ''}"><p class="образ__вопрос">${вопрос}</p>${состояние(знак, строка, знак === 'не-размечено' ? 'мы' : 'библия')}</li>`;

  // паспорт истории в шапке: малый знак тонкой линией и сведения (В-25: справочное издание, не иллюстрация)
  function паспорт(знак, подпись, строки) {
    return `<aside class="паспорт" aria-label="Паспорт истории"><figure class="паспорт__знак">${знак}<figcaption class="паспорт__подпись">${подпись}</figcaption></figure>` +
      `<dl class="паспорт__сведения">${строки.map(([a, b]) => `<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl></aside>`;
  }

  // цитаты одного стиха — одной строкой с одной адрес-кнопкой
  function группы(цц) { const г = []; for (const ц of цц) { const п = г[г.length - 1]; if (п && п[0] === ц.стих) п[1].push(ц.цитата); else г.push([ц.стих, [ц.цитата]]); } return г; }
  function лицо(к, { знак, скрытое = '', строка = '', ещё = '' }) {
    return `<li class="лицо"${к.новое ? ' data-новое' : ''}>${знак}<div class="лицо__тело">${скрытое ? `<span class="скрыто">${скрытое}: </span>` : ''}<a class="лицо__имя" href="${НЕТ}">${экр(к.имя)}</a>` +
      `${строка ? состояние('не-сказано', строка) : ''}${группы(к.цитаты || [к]).map(([ст, цц]) => `<p class="лицо__роль">Библия: ${цц.map((ц) => `«${экр(ц)}»`).join(', ')}</p>${вклейка(ст)}`).join('')}${ещё}</div></li>`;
  }
  const знакЛица = (вид) => вид ? З.значок(вид, 'знак-лица') : '<span class="знак-лица знак-лица--нет"></span>';

  function метаВторого(пары) {
    return слой2() ? `<dl class="мета">${пары.map(([a, b]) => `<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>` : '';
  }
  function соседи(д, строкаКниги) {
    const п = д.предыдущая, с = д.следующая;
    return `<ul class="соседи"><li class="сосед"><span class="сосед__строка">${строкаКниги[0]}</span><a class="сосед__название" href="${НЕТ}">${экр(п.название)}</a><span class="к-адрес">${адрес(п.стихи)}</span></li>` +
      `<li class="сосед сосед--следующая"><span class="сосед__строка">${строкаКниги[1]}</span><a class="сосед__название" href="${НЕТ}">${экр(с.название)}</a><span class="к-адрес">${адрес(с.стихи)}</span></li></ul>`;
  }
  function кнопкаИзучающих() {
    return слой2()
      ? `<button type="button" class="кнопка кнопка--текст" data-слой-на="1">Вернуться к простому виду</button>`
      : `<button type="button" class="кнопка кнопка--текст" data-слой-на="2">Показать для изучающих: скобки, толкования, источники</button>`;
  }

  // ==================== шапка сайта ====================
  function шапкаСайта() {
    $('#шапка').innerHTML = `
      <a class="шапка__знак" href="${НЕТ}">Библия наглядно</a>
      <button class="кнопка сайт__меню" type="button" aria-expanded="false" aria-controls="сайт-панель">${З.значок('меню')}Меню</button>
      <div class="сайт__панель" id="сайт-панель">
        <form class="поиск шапка__поиск" role="search" action="${НЕТ}">
          <label class="скрыто" for="поиск">Поиск</label>
          <div class="поиск__поле">${З.значок('поиск')}<input id="поиск" type="search" placeholder="История, человек, место или стих" autocomplete="off"></div>
        </form>
        <div class="сегменты" role="group" aria-label="Вид">
          <button type="button" data-слой-кнопка="1">Простой вид</button><button type="button" data-слой-кнопка="2">Для изучающих</button>
        </div>
        <a class="сайт__ссылка" href="${НЕТ}">${З.значок('справка')}Справка</a>
      </div>`;
  }

  // ==================== экран 2: Ной и потоп ====================
  function ной() {
    const д = И.ной, ш = д.шапка, о = д.о_чём, кто = д.кто_в_истории, ист = д.история, где = д.где_об_этом, дал = д.в_книге_дальше;
    const множитель = q.get('множитель') === '1';
    const образШапки = множитель
      ? `<div class="множители" role="group" aria-label="Тёмный множитель рисунка: три варианта">${['1', '0.85', '0.66'].map((м) => `<figure class="множитель"><div class="поле-рисунка" style="--множитель:${м}">${ЗИ.ковчег()}</div><figcaption class="к-адрес">Множитель ${м.replace('.', ',').replace(/^1$/, '1,00')}</figcaption></figure>`).join('')}</div>`
      : паспорт(ЗИ.ковчег(), `Временный знак: ковчег. ${экр(ш.обложка.подпись_на_снимке)}`, [
        ['Где', `<span>${экр(о.где.текст.split('. ')[1])}. <span class="к-адрес">${адрес(о.где.стихи[0])}</span></span>${состояние('не-сказано', экр(о.где.текст.split('. ')[0]) + '.')}`],
        ['Когда', `<span>${экр(о.когда.текст.replace(/^Когда: /, ''))}. <span class="к-адрес">${адрес(о.когда.стих)}</span></span>${эпохи('antediluvian')}`],
        ['Объём', `${д.числа.частей} частей, ${д.числа.стихов} стиха`],
      ]);
    const шапка = `<header class="история-шапка история-шапка--вз${множитель ? ' история-шапка--множитель' : ''}" id="шапка-истории">
      <div class="история-шапка__текст">
        ${путь(ш.путь)}
        <p class="номер-истории номер-истории--вз к-номер-истории история-шапка__номер"><span class="скрыто">Номер в книге: </span>${ш.второй_слой.номер_в_книге}</p>
        <h1 class="к-название-истории история-шапка__название" tabindex="-1">${экр(ш.название)}</h1>
        <p class="история-шапка__адрес">${адрес(ш.адрес)}</p>
        <p class="тихая-строка история-шапка__трудная">${экр(ш.трудная.строка)}</p>
        ${метаВторого([['Пометка', ш.второй_слой.пометка], ['Вид', ш.второй_слой.вид], ['Частей', ш.второй_слой.частей], ['Сверка', ш.второй_слой.сверка]])}
      </div>
      ${образШапки}
    </header>`;

    const адресаФормулы = о.простой_слой.flatMap((x) => x.стихи);
    const очём = блок('о-чём', 'О чём эта история', `
      <p class="подпись-блока">${экр(о.подпись)}</p>
      ${слой2()
        ? `<ol class="коротко-полно">${о.второй_слой.map((x) => `<li><span class="к-коротко">${экр(x.текст)}</span> <span class="к-адрес">${x.стихи.map(адрес).join('; ')}</span>${x.напряжение ? `<span class="пометка">${экр(x.напряжение)}</span>` : ''}</li>`).join('')}</ol>`
        : `<p class="коротко">${о.простой_слой.map((x) => экр(x.текст)).join(' ')}</p><p class="формула к-адрес">${экр(о.формула)}</p>`}
      ${слой2() ? `<p class="пометка">Когда, расч.: ${экр(о.когда.второй_слой)}</p>` : ''}`);
    void адресаФормулы;

    const знаки = { мужчина: 'мужчина', женщина: 'женщина', группа: 'группа' };
    const карточка = (к) => {
      const птица = к.скрытое_слово === 'птица';
      const знак = птица ? `<span class="знак-лица знак-лица--предмет">${к.имя === 'ворон' ? З.предмет('ворон') : ЗИ.голубь()}</span>` : знакЛица(знаки[к.знак] || 'группа');
      const назван = слой2() && (к.назван_ещё || (к.лица && к.лица.length))
        ? `<p class="пометка">${к.назван_ещё ? экр(к.назван_ещё.строка) : к.лица.map((л) => экр(л.назван_ещё.строка)).join('<br>')}</p>` : '';
      return лицо(к, { знак, скрытое: к.скрытое_слово || '', строка: к.строка || '', ещё: назван });
    };
    const лица = блок('кто', 'Кто в этой истории', `
      <p class="строка-бога">${цитата(кто.бог.цитата, кто.бог.стих)}</p>
      <ul class="лица" id="лица">${кто.карточки.map(карточка).join('')}${кто.ещё.карточки.map((к) => карточка({ ...к, новое: true }).replace('<li class="лицо"', '<li class="лицо" hidden')).join('')}</ul>
      <button type="button" class="кнопка кнопка--текст" aria-expanded="false" aria-controls="лица" data-ещё-лица aria-label="${экр(кто.ещё.кнопка_имя)}">${экр(кто.ещё.кнопка)}${З.значок('раскрыть', 'значок-раскрыть')}</button>`);

    const узнать = блок('узнать', 'Узнать больше', `<ul class="образы">
      ${образ('Где это было?', 'География', `<span class="образ__ответ">горы Араратские</span>`)}
      ${образ('Чья это семья?', 'Генеалогия', `<span class="образ__ответ">Ной, его жена и сыновья: Сим, Хам, Иафет</span>`)}
      ${образ('Когда это было?', 'Время', `<span class="образ__ответ">${экр(И.эпохи[0].имя)}</span>`)}
      ${образНет('Кто кого знал?', 'Связи — скоро', 'не-размечено', true)}
    </ul>`);

    const открыть = слой2() || q.get('открыть') === '1';
    const части = ист.части.map((ч) => {
      const id = `часть-${ч.n}`; const [кн, гл, от, до] = ч.стихи.match(/^(\S+) (\d+):(\d+)-(\d+)$/).slice(1);
      const адреса = []; for (let v = +от; v <= +до; v++) адреса.push(`${кн} ${гл}:${v}`);
      const пояс = ч.n === 1 ? `<dl class="пояснения">${ист.пояснения.map((п) => `<div><dt>${экр(п.слово)}</dt><dd>${экр(п.текст.replace(/^\S+ — /, ''))}</dd></div>`).join('')}<p class="пометка">Справочно: это пояснения, не слова Библии</p></dl>` : '';
      const раскрыта = открыть && (слой2() || ч.n === 1);
      return `<li class="часть">
        <h3 class="часть__заголовок"><button type="button" class="часть__кнопка" aria-expanded="${раскрыта}" aria-controls="${id}" aria-label="${экр(ч.кнопка)}, ${экр(полныйАдрес(ч.стихи))}">
          <span class="часть__номер номер-истории номер-истории--вз" aria-hidden="true">${ч.n}</span>
          <span class="часть__слова"><span class="часть__читать">Читать часть ${ч.n}:</span> <span class="часть__название">${экр(ч.название)}</span></span>
          ${З.значок('раскрыть', 'часть__значок')}</button></h3>
        <p class="часть__адрес к-адрес">${адрес(ч.стихи)}</p>
        <div class="часть__текст" id="${id}" ${раскрыта ? '' : 'hidden="until-found"'}>
          <blockquote class="писание к-текст-писания"><p>${текстЧасти(адреса, { буквица: q.get('буквица') === '1' })}</p></blockquote>${пояс}</div>
      </li>`;
    }).join('');
    const история = блок('история', 'История', `
      <div class="история__над"><p class="так-написано">${экр(ист.строка)}</p><button type="button" class="кнопка кнопка--текст" data-все-части aria-expanded="${слой2()}">${слой2() ? 'Закрыть все части' : экр(ист.открыть_все)}</button></div>
      <ol class="части">${части}</ol>
      <div class="найдите"><h3 class="к-заголовок-аппарата">Найдите вместе</h3><ul>${ист.найдите_вместе.map((н) => `<li><span class="найдите__вопрос">${экр(н.вопрос)}</span> ${вклейка(н.стих)}</li>`).join('')}</ul></div>`, 'блок--история');

    const упом = где.упоминания.места;
    const как = Object.fromEntries(где.таблица_двойник_полосы.map((x) => [x.книга, x.как.startsWith('рассказ') ? 'рассказ' : 'упоминание']));
    const двойник = `<div class="${слой2() ? '' : 'скрыто'}"><table class="двойник"><caption>Все найденные места; как искали — опись полноты</caption><thead><tr><th scope="col">Книга</th><th scope="col">Как говорит</th><th scope="col">Места</th></tr></thead><tbody>
      <tr><th scope="row">Бытие</th><td>рассказано</td><td>${адрес('Быт 6:9-9:17')}</td></tr>
      <tr><th scope="row">Исаия</th><td>вспоминает</td><td>Ис 54:9</td></tr>
      <tr><th scope="row">Евангелие от Матфея</th><td>вспоминает</td><td>${адрес('Мф 24:37-39')}</td></tr>
      <tr><th scope="row">Евангелие от Луки</th><td>вспоминает</td><td>${адрес('Лк 17:26-27')}</td></tr>
      <tr><th scope="row">Первое послание Петра</th><td>вспоминает</td><td>${адрес('1Пет 3:20')}</td></tr>
      <tr><th scope="row">Второе послание Петра</th><td>вспоминает; похоже, вспоминает</td><td>${адрес('2Пет 2:5')}; ${адрес('2Пет 3:6')}</td></tr>
      <tr><th scope="row">Послание к Евреям</th><td>пересказывает</td><td>${адрес('Евр 11:7')}</td></tr></tbody></table></div>`;
    const местоУп = (м, скрыто) => `<li class="место"${скрыто ? ' hidden data-ещё-место' : ''}>${цитата(м.цитата, м.стих)}</li>`;
    const гдеБлок = блок('где', 'Где об этом в Библии', `
      <div class="подпись-блока подпись-блока--ряд"><span>Все найденные места.</span> <button type="button" class="кнопка кнопка--текст кнопка--мелко" aria-expanded="false" aria-controls="как-искали">Как искали${З.значок('раскрыть', 'значок-раскрыть')}</button></div>
      <p class="пометка" id="как-искали" hidden>${экр(где.как_искали)}</p>
      ${полоса(как)}
      <p class="охват">${экр(где.охват_строка)}</p>
      <ul class="места">
        <li class="места__вид"><p class="места__строка">${экр(где.рассказ[0].строка)}</p></li>
        <li class="места__вид"><p class="места__строка">${экр(где.пересказ[0].строка)}</p><ul>${местоУп(где.пересказ[0])}</ul></li>
        <li class="места__вид"><p class="места__строка">${экр(где.упоминания.строка)}</p><ul id="ещё-места">${упом.map((м, i) => местоУп(м, i >= 3)).join('')}</ul>
          <button type="button" class="кнопка кнопка--текст" aria-expanded="false" aria-controls="ещё-места" data-ещё-места>Показать ещё 2 места${З.значок('раскрыть', 'значок-раскрыть')}</button></li>
        <li class="места__вид"><p class="места__строка">${экр(где.намёк[0].строка)}</p><ul>${местоУп(где.намёк[0])}</ul></li>
        <li class="места__вид"><p class="места__строка"><a href="${НЕТ}">${экр(где.только_имя.строка)}</a></p></li>
        ${слой2() ? `<li class="места__вид">${состояние('спорно', 'Спорное сравнение: «' + экр(где.спорное_только_второй_слой[0].цитата) + '» (Пс 28:10). Ещё не разобрано по правилам толкований (Г-1–Г-7); до разбора на странице его не будет', 'мы')}</li>
          <li class="места__вид"><p class="места__строка">В той же книге</p><ul>${где.в_той_же_книге_второй_слой.map((м) => местоУп(м)).join('')}</ul></li>` : ''}
      </ul>
      ${двойник}`);

    const дальше = блок('дальше', 'В книге дальше', `
      ${соседи(дал, [дал.предыдущая.строка, дал.следующая.строка])}
      <h3 class="к-заголовок-аппарата">Повествование «${экр(дал.повествование.название)}»</h3>
      <ol class="повествование">${дал.повествование.истории.map((x) => x.текущая
        ? `<li class="повествование__тек"><a href="#шапка-истории" aria-current="page">${экр(x.название)}</a> <span aria-hidden="true">(вы здесь)</span> <span class="к-адрес">${адрес(x.стихи)}</span></li>`
        : `<li><a href="${НЕТ}">${экр(x.название)}</a> <span class="к-адрес">${адрес(x.стихи)}</span></li>`).join('')}</ol>
      ${слой2() ? `<p class="пометка">${экр(дал.по_времени_второй_слой)}</p>` : ''}`);

    const изуч = д.для_изучающих;
    const изучающим = блок('изучающим', 'Для изучающих', `${кнопкаИзучающих()}
      ${слой2() ? `<p class="к-проза">В скобках Синодального издания — ${изуч.скобки_второй_слой.мест} мест: ${изуч.скобки_второй_слой.по_видам.lxx} вида «а» (нет в еврейском тексте, есть в греческом) и ${изуч.скобки_второй_слой.по_видам.added} вида «в» (слово добавлено для ясности). Они набраны тем же цветом, знаки скобок видны.</p>
        <ul class="напряжения">${изуч.напряжение_для_04.map((н) => `<li class="к-проза">${экр(н)}</li>`).join('')}</ul>
        <p class="пометка">${экр(изуч.колофон)}</p>` : ''}`);

    return шапка + `<div class="история-тело история-тело--вз">${очём}<div class="боковая">${лица}${узнать}</div>${история}${гдеБлок}${дальше}${изучающим}</div>`;
  }

  // ==================== экран 3: Расслабленного спускают через кровлю ====================
  function расслабленный() {
    const д = И.расслабленный, ш = д.шапка, о = д.о_чём, кто = д.кто_в_истории, ист = д.история, раз = д.различия, где = д.где_об_этом, дал = д.в_книге_дальше;
    const тек = ['Мф', 'Мк', 'Лк'].includes(q.get('рассказ')) ? q.get('рассказ') : 'Мк';
    const рассказ = д.рассказы.find((р) => р.книга === тек);
    const эпиграф = `<figure class="эпиграф">
        <blockquote class="эпиграф__стих голос-библии"><p>«${экр(ш.эпиграф.цитата)}»</p></blockquote>
        <figcaption class="эпиграф__адрес">${вклейка(ш.эпиграф.стих)}</figcaption></figure>`;
    const паспортШапки = паспорт(ЗИ.постель(), 'Временный знак: постель и кровля. Рисунка у этой истории нет', [
      ['Где', `<span>${экр(о.где.текст.replace(/^Где: /, ''))}, по рассказу Марка. <span class="к-адрес">${адрес(о.где.стихи[0])}</span></span>`],
      ['Когда', `${состояние('не-сказано', экр(о.когда.текст) + '.')}${эпохи('christ')}`],
      ['Рассказы', д.рассказы.map((р) => адрес(р.стихи)).join(', ')],
    ]);
    const шапка = `<header class="история-шапка история-шапка--нз" id="шапка-истории">
      <div class="история-шапка__текст">
        ${путь(ш.путь)}
        <p class="номер-истории к-номер-истории история-шапка__номер"><span class="скрыто">Номер в книге: </span>${ш.второй_слой.номер_в_книге_Мк}</p>
        <h1 class="к-название-истории история-шапка__название" tabindex="-1">${экр(ш.название)}</h1>
        <p class="история-шапка__адрес">${адрес(рассказ.стихи)} и ещё 2 рассказа</p>
        ${метаВторого([['Пометка', ш.второй_слой.пометка], ['Вид', ш.второй_слой.вид], ['Рассказов', ш.второй_слой.рассказов], ['Сверка', ш.второй_слой.сверка]])}
      </div>
      ${паспортШапки}
      ${эпиграф}
    </header>`;

    const очём = блок('о-чём', 'О чём эта история', `
      <p class="подпись-блока">${экр(о.подпись)}</p>
      ${слой2()
        ? `<ol class="коротко-полно">${о.второй_слой.map((x) => `<li><span class="к-коротко">${экр(x.текст)}</span> <span class="к-адрес">${x.стихи.map(адрес).join('; ')}</span></li>`).join('')}</ol>`
        : `<p class="коротко">${о.простой_слой.map((x) => экр(x.текст)).join(' ')}</p><p class="формула к-адрес">${экр(о.формула)}</p>`}
      ${слой2() ? `<p class="пометка">${экр(о.где.примечание)}; ${экр(о.когда.второй_слой)}</p>` : ''}`);

    const знаки = { мужчина: 'мужчина', группа: 'группа' };
    const лица = блок('кто', 'Кто в этой истории', `<ul class="лица">${кто.карточки.map((к) => лицо(к, {
      знак: знакЛица(знаки[к.знак]), скрытое: к.знак === 'группа' ? 'группа' : '', строка: к.строка || '',
      ещё: слой2() && к.примечание ? `<p class="пометка">${экр(к.примечание)}</p>` : '' })).join('')}</ul>`);

    const узнать = блок('узнать', 'Узнать больше', `<ul class="образы">
      ${образ('Где это было?', 'География', `<span class="образ__ответ">${экр(ш.паспорт.место.имя)} — по рассказу Марка</span>`)}
      ${образНет('Чья это семья?', экр(д.узнать_больше[2].строка), 'не-сказано')}
      ${образ('Когда это было?', 'Время', `<span class="образ__ответ">${экр(ш.паспорт.эпоха.имя)}</span>`)}
      ${образНет('Кто кого знал?', 'Связи — скоро', 'не-размечено', true)}
    </ul>`);

    // текст: простой слой — рассказ книги входа; второй — вкладки трёх рассказов (APG Tabs)
    const адреса = (р) => { const [кн, гл, от, до] = р.стихи.match(/^(\S+) (\d+):(\d+)-(\d+)$/).slice(1); const a = []; for (let v = +от; v <= +до; v++) a.push(`${кн} ${гл}:${v}`); return a; };
    const ИМЯ = { Мф: 'Матфей', Мк: 'Марк', Лк: 'Лука' };
    const вкладки = слой2() ? `<div class="вкладки" role="tablist" aria-label="Рассказы">${д.рассказы.map((р) => `<button type="button" role="tab" id="вкладка-${р.книга}" aria-selected="${р.книга === тек}" aria-controls="рассказ" tabindex="${р.книга === тек ? 0 : -1}" data-рассказ="${р.книга}">${ИМЯ[р.книга]}<span class="скрыто"> — ${экр(р.строка)}</span></button>`).join('')}</div>` : '';
    const история = блок('история', 'История', `
      <div class="история__над"><p class="так-написано">${экр(ист.строка)}</p></div>
      ${вкладки}
      <div class="рассказ" id="рассказ" ${слой2() ? `role="tabpanel" aria-labelledby="вкладка-${тек}" tabindex="0"` : ''}>
        <p class="рассказ__книга"><span class="рассказ__имя">${экр(рассказ.строка)}</span> <span class="к-адрес">${адрес(рассказ.стихи)}</span></p>
        <blockquote class="писание писание--нз к-текст-писания"><p>${текстЧасти(адреса(рассказ), { буквица: q.get('буквица') === '1' })}</p></blockquote>
      </div>
      ${слой2() ? '' : `<p class="три-рассказа">Об этом рассказывают три Евангелия. <button type="button" class="кнопка кнопка--текст" data-слой-на="2">Показать для изучающих: три рассказа</button></p>`}`, 'блок--история');

    const ячейка = (x) => x ? `<span class="различие__слова">«${экр(x.цитата)}»</span> <span class="к-адрес">${адрес(x.стих)}</span>${x.ещё ? `<br><span class="различие__слова">«${экр(x.ещё.цитата)}»</span> <span class="к-адрес">${адрес(x.ещё.стих)}</span>` : ''}${x.итог ? `<span class="различие__итог">${З.значок('не-сказано')}${экр(x.итог)}</span>` : ''}` : '';
    const различия = `<div class="таблица-обёртка" role="region" aria-label="Различия рассказов" tabindex="0"><table class="различия"><caption>Различия рассказов: слова каждого рассказа — его стих; подробность одного рассказа не переносится в другой</caption>
      <thead><tr><th scope="col">Что</th><th scope="col">Матфей</th><th scope="col">Марк</th><th scope="col">Лука</th></tr></thead>
      <tbody>${раз.строки.map((с) => `<tr><th scope="row">${экр(с.что)}</th><td>${ячейка(с.Мф)}</td><td>${ячейка(с.Мк)}</td><td>${ячейка(с.Лк)}</td></tr>`).join('')}</tbody></table></div>`;
    const нет = (v) => v === 'нет' ? `<span class="различие__итог">${З.значок('не-сказано')}нет этого слова</span>` : `<span class="к-адрес">${экр(v)}</span>`;
    const подробности = `<div class="таблица-обёртка" role="region" aria-label="Подробности по рассказам" tabindex="0"><table class="различия различия--подробности"><caption>Подробности по рассказам: где стоит слово (посчитала программа)</caption>
      <thead><tr><th scope="col">Слово</th><th scope="col">Матфей</th><th scope="col">Марк</th><th scope="col">Лука</th></tr></thead>
      <tbody>${д.подробности_программа.map((с) => `<tr><th scope="row">${экр(с.подробность)}</th><td>${нет(с.Мф)}</td><td>${нет(с.Мк)}</td><td>${нет(с.Лк)}</td></tr>`).join('')}</tbody></table></div>`;
    const сцены = `<div class="таблица-обёртка" role="region" aria-label="Сцены трёх рассказов" tabindex="0"><table class="различия"><caption>Строки — сцены (подпись атласа). Слова рассказов не сливаются; различия названы словами</caption>
      <thead><tr><th scope="col">Сцена</th><th scope="col">Матфей</th><th scope="col">Марк</th><th scope="col">Лука</th></tr></thead>
      <tbody>${ист.сцены_второй_слой.map((с) => `<tr><th scope="row">${экр(с.сцена)}</th>${['Мф', 'Мк', 'Лк'].map((к) => `<td>${/^нет/.test(с[к]) ? `<span class="различие__итог">${З.значок('не-сказано')}нет этой сцены</span>` : `<span class="к-адрес">${экр(с[к])}</span>`}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;

    const как = { Мф: 'рассказ', Мк: 'рассказ', Лк: 'рассказ' };
    const гдеБлок = блок('где', 'Где об этом в Библии', `
      <div class="подпись-блока подпись-блока--ряд"><span>Все найденные места.</span> <button type="button" class="кнопка кнопка--текст кнопка--мелко" aria-expanded="false" aria-controls="как-искали">Как искали${З.значок('раскрыть', 'значок-раскрыть')}</button></div>
      <p class="пометка" id="как-искали" hidden>${экр(где.как_искали)}</p>
      ${полоса(как)}
      <div class="${слой2() ? '' : 'скрыто'}"><table class="двойник"><caption>Все найденные места; как искали — опись полноты</caption><thead><tr><th scope="col">Книга</th><th scope="col">Как говорит</th><th scope="col">Места</th></tr></thead><tbody>
        ${где.рассказ.map((р) => `<tr><th scope="row">${КНИГИ[р.стихи.split(' ')[0]][0]}</th><td>рассказано</td><td>${адрес(р.стихи)}</td></tr>`).join('')}</tbody></table></div>
      <ul class="места">
        <li class="места__вид"><p class="места__строка">${экр(где.строка)}</p></li>
        <li class="места__вид"><p class="места__мы">${экр(где.строка_пустого)}</p></li>
        <li class="места__вид"><p class="места__строка">${экр(раз.строка_простого_слоя)}</p>
          <button type="button" class="кнопка кнопка--текст" aria-expanded="${слой2()}" aria-controls="различия">${экр(раз.кнопка)}${З.значок('раскрыть', 'значок-раскрыть')}</button>
          <div id="различия" ${слой2() ? '' : 'hidden'}>${различия}</div></li>
        ${слой2() ? `<li class="места__вид"><h3 class="к-заголовок-аппарата">Подробности по рассказам</h3>${подробности}</li><li class="места__вид"><h3 class="к-заголовок-аппарата">Сцены по рассказам</h3>${сцены}</li>` : ''}
      </ul>`);

    const дальше = блок('дальше', 'В книге дальше', `
      ${соседи(дал, ['Предыдущая в Евангелии от Марка', 'Следующая в Евангелии от Марка'])}
      ${слой2() ? `<p class="пометка">В других рассказах: ${дал.соседи_в_других_рассказах_второй_слой.map((с) => `${КНИГИ[с.книга][0]} — до ${адрес(с.до)}, после ${адрес(с.после)}`).join('; ')}. ${экр(дал.соседи_примечание)}</p>` : ''}`);

    const изучающим = блок('изучающим', 'Для изучающих', `${кнопкаИзучающих()}
      ${слой2() ? `<p class="к-проза">${экр(д.для_изучающих.скобки)}.</p><p class="к-проза">${экр(раз.правило)}.</p><p class="пометка">${экр(д.для_изучающих.колофон)}</p>` : ''}`);

    return шапка + `<div class="история-тело">${очём}<div class="боковая">${лица}${узнать}</div>${история}${гдеБлок}${дальше}${изучающим}</div>`;
  }

  // ==================== отрисовка и поведение ====================
  function подвал() {
    $('#о-прототипе').innerHTML = `<p>Прототип шага 0, направление ${корень.dataset.dir === 'b' ? 'Б «Книга с рубриками»' : 'А «Иллюстрированный атлас»'}. Не продукт. Данные предварительные: размечены одним составителем, без второго ключа. Знаки временные, нарисованы составителем, не художником. Ссылки ведут на строку «Этот экран в эскизе не нарисован».</p>`;
  }
  function отрисовать() {
    счётчик = 0;
    $('#страница').innerHTML = ЭКРАН === 'ной' ? ной() : расслабленный();
    $$('[data-слой-кнопка]').forEach((b) => b.setAttribute('aria-pressed', String((корень.dataset.layer || '1') === b.getAttribute('data-слой-кнопка'))));
    подвал();
  }
  function сменитьСлой(с, фокус) {
    if ((корень.dataset.layer || '1') === с) return;
    // якорь прокрутки: верхний видимый блок остаётся у верхнего края (08 § 7.9)
    const блоки = $$('#страница > header, .блок'); const верх = блоки.find((b) => b.getBoundingClientRect().bottom > 0);
    const id = верх && верх.id; const сдвиг = верх ? верх.getBoundingClientRect().top : 0;
    корень.dataset.layer = с;
    const u = new URL(location.href); if (с === '2') u.searchParams.set('layer', '2'); else u.searchParams.delete('layer'); history.replaceState(null, '', u);
    отрисовать();
    if (id && document.getElementById(id)) window.scrollBy(0, document.getElementById(id).getBoundingClientRect().top - сдвиг);
    $('#объявление').textContent = с === '2' ? 'Показаны номера стихов, все части, пометки и источники' : 'Показан простой вид';
    if (фокус) { const f = document.querySelector(фокус); if (f) f.focus(); }
  }
  function раскрыть(b, откр) {
    b.setAttribute('aria-expanded', String(откр));
    const el = document.getElementById(b.getAttribute('aria-controls'));
    if (!el) return;
    if (b.hasAttribute('data-ещё-лица')) { $$('[data-новое]', el).forEach((x) => { x.hidden = !откр; }); if (откр) { const f = $('[data-новое] .лицо__имя', el); if (f) f.focus(); } return; }
    if (b.hasAttribute('data-ещё-места')) { $$('[data-ещё-место]', el).forEach((x) => { x.hidden = !откр; }); b.firstChild.textContent = откр ? 'Скрыть 2 места' : 'Показать ещё 2 места'; return; }
    if (откр) el.removeAttribute('hidden'); else if (el.classList.contains('часть__текст')) el.setAttribute('hidden', 'until-found'); else el.hidden = true;
  }
  document.addEventListener('click', (e) => {
    const b = e.target.closest('button'); if (!b) return;
    if (b.hasAttribute('data-слой-кнопка')) { const с = b.getAttribute('data-слой-кнопка'); сменитьСлой(с, `[data-слой-кнопка="${с}"]`); return; }
    if (b.hasAttribute('data-слой-на')) { сменитьСлой(b.getAttribute('data-слой-на'), '#изучающим [data-слой-на]'); return; }
    if (b.hasAttribute('data-все-части')) {
      const откр = b.getAttribute('aria-expanded') !== 'true'; b.setAttribute('aria-expanded', String(откр));
      b.textContent = откр ? 'Закрыть все части' : 'Открыть все части';
      $$('.часть__кнопка').forEach((x) => раскрыть(x, откр)); return;
    }
    if (b.getAttribute('role') === 'tab') { выбратьРассказ(b.dataset.рассказ); return; }
    if (b.classList.contains('сайт__меню')) { const о = b.getAttribute('aria-expanded') !== 'true'; b.setAttribute('aria-expanded', String(о)); $('#шапка').dataset.меню = о ? 'открыто' : ''; return; }
    if (b.hasAttribute('aria-expanded') && b.getAttribute('aria-controls')) раскрыть(b, b.getAttribute('aria-expanded') !== 'true');
  });
  function выбратьРассказ(к) {
    const u = new URL(location.href); u.searchParams.set('рассказ', к); history.replaceState(null, '', u);
    q.set('рассказ', к); отрисовать(); const t = $(`#вкладка-${к}`); if (t) t.focus();
  }
  document.addEventListener('keydown', (e) => {
    const t = e.target;
    if (t.getAttribute && t.getAttribute('role') === 'tab' && ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(e.key)) {
      const все = $$('[role="tab"]'); const i = все.indexOf(t);
      const н = e.key === 'Home' ? 0 : e.key === 'End' ? все.length - 1 : (i + (e.key === 'ArrowRight' ? 1 : -1) + все.length) % все.length;
      e.preventDefault(); выбратьРассказ(все[н].dataset.рассказ); return;
    }
    if (e.key === 'Escape') {
      const место = t.closest && t.closest('.вклейка-место');
      if (место) { const b = $('.адрес-кнопка', место); раскрыть(b, false); b.focus(); return; }
      const ш = $('#шапка'); if (ш.dataset.меню === 'открыто') { const b = $('.сайт__меню'); раскрыть(b, false); b.setAttribute('aria-expanded', 'false'); ш.dataset.меню = ''; b.focus(); }
    }
  });
  // поиск по странице находит свёрнутую часть: раскрываем и ставим кнопку в «раскрыто»
  document.addEventListener('beforematch', (e) => { const b = document.querySelector(`[aria-controls="${e.target.id}"]`); if (b) b.setAttribute('aria-expanded', 'true'); });

  шапкаСайта();
  отрисовать();
  // проверка шрифтов для снимков: «Й Ё ё й» обоими шрифтами направления
  (async () => {
    await document.fonts.ready;
    const b = корень.dataset.dir === 'b';
    const семьи = b ? ['Piazzolla', 'Ysabeau Office'] : ['Literata', 'Golos Text'];
    await Promise.all(семьи.map((с) => document.fonts.load(`600 20px "${с}"`, 'ЙЁёй')));
    const ок = семьи.every((с) => [...document.fonts].some((f) => f.family.replace(/"/g, '') === с && f.status === 'loaded'));
    корень.dataset.fonts = ок ? 'ok' : 'нет';
  })();
})();
